#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  RECT cr;  int frame,fill;  } Queue_Arc;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintArc(DefinePaint)  {  QueueP(Queue_Arc);  if ( p->frame && p->fill )    {    ::Chord( hDC, p->cr.left, p->cr.top, p->cr.right, p->cr.bottom,                  p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );    }  else  if ( p->frame || p->fill )    {    ::BeginPath( hDC );    ::Arc( hDC, p->cr.left, p->cr.top, p->cr.right, p->cr.bottom,                p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );    ::EndPath ( hDC );    if ( p->fill )      ::FillPath(hDC);    else      ::StrokePath(hDC);    }  else    {    ::Arc( hDC, p->cr.left, p->cr.top, p->cr.right, p->cr.bottom,                p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddArc(DefineTegs)  {  RECT rect;  if ( !ParserRect(teg[0].value,rect) ) return;  AddQueueEx(Queue_Arc);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintArc;  //  STegObj obj[] =    {    { 'R', "rect" , &p->cr    },    { 'E', "rc"   , &p->cr    },    { 'I', "frame", &p->frame },    { 'I', "fill" , &p->fill  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->mRect = rect;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~